def load() -> pd.DataFrame:
    import pandas as pd
    import glob
    pattern = 'data/astronomy/input/swarmb/SB_DNS_POD_2024_*.txt'
    files = sorted(glob.glob(pattern))
    if not files:
        raise FileNotFoundError(f'No files matched: {pattern}')
    return pd.DataFrame({'file': files})

def process(swarmBParse, omniParse2024) -> pd.DataFrame:
    import numpy as np
    import pandas as pd

    try:
        from pymsis import msis
    except Exception as e:
        return pd.DataFrame({'error':[f'pymsis import failed: {e}'], 'n':[0]})

    sw = swarmBParse.copy()
    om = omniParse2024.copy()

    if 'error' in sw.columns:
        return pd.DataFrame({'error':[str(sw.iloc[0].get('error'))], 'n':[0]})
    if 'error' in om.columns:
        return pd.DataFrame({'error':[str(om.iloc[0].get('error'))], 'n':[0]})

    req_sw = {'timestamp','lat_deg','lon_deg','alt_km','rho_meas'}
    req_om = {'timestamp','ap','f107','f107a'}
    if not req_sw.issubset(sw.columns):
        return pd.DataFrame({'error':[f'Missing Swarm columns: {sorted(req_sw - set(sw.columns))}'], 'n':[0]})
    if not req_om.issubset(om.columns):
        return pd.DataFrame({'error':[f'Missing OMNI columns: {sorted(req_om - set(om.columns))}'], 'n':[0]})

    sw = sw.dropna(subset=['timestamp','lat_deg','lon_deg','alt_km','rho_meas'])
    sw = sw[(sw['rho_meas']>0) & (sw['alt_km']>0) & (sw['alt_km']<2000)]

    om = om.dropna(subset=['timestamp','ap','f107'])

    # 3-hour bin on OMNI timestamps
    om['timestamp'] = pd.to_datetime(om['timestamp'], utc=True)
    om['t3'] = om['timestamp'].dt.floor('3h')
    ap3 = om.groupby('t3', as_index=False).agg(
        ap3=('ap','mean'),
        f107=('f107','mean'),
        f107a=('f107a','mean')
    )

    # daily Ap from hourly ap
    om['day'] = om['timestamp'].dt.floor('D')
    daily = om.groupby('day', as_index=False).agg(dailyAp=('ap','mean'))

    ap3['day'] = ap3['t3'].dt.floor('D')
    ap3 = ap3.merge(daily, on='day', how='left')

    ap3 = ap3.sort_values('t3').reset_index(drop=True)
    # build shifted ap3 series by 3h steps
    for k, shift in [('ap0',0),('apm3',1),('apm6',2),('apm9',3)]:
        ap3[k] = ap3['ap3'].shift(shift)

    # means for windows: 12-33h => bins 4..11 back (8 bins)
    ap3['apm12to33'] = pd.concat([ap3['ap3'].shift(i) for i in range(4,12)], axis=1).mean(axis=1, skipna=False)
    # 36-57h => bins 12..19 back
    ap3['apm36to57'] = pd.concat([ap3['ap3'].shift(i) for i in range(12,20)], axis=1).mean(axis=1, skipna=False)

    # Construct aps vector per row
    ap3['aps'] = ap3.apply(lambda r: [r['dailyAp'], r['ap0'], r['apm3'], r['apm6'], r['apm9'], r['apm12to33'], r['apm36to57']], axis=1)

    drivers = ap3[['t3','f107','f107a','aps']].copy()

    # bin swarm to 3-hour
    sw['timestamp'] = pd.to_datetime(sw['timestamp'], utc=True)
    sw['t3'] = sw['timestamp'].dt.floor('3h')

    merged = sw.merge(drivers, on='t3', how='inner')
    if merged.empty:
        return pd.DataFrame({'error':['No Swarm samples matched to OMNI 3-hour bins'], 'n':[0]})

    # ensure finite
    merged = merged.dropna(subset=['f107','f107a'])
    merged = merged[merged['rho_meas'].notna()]

    # Prepare inputs for pymsis
    times = merged['timestamp'].dt.to_pydatetime()
    lats = merged['lat_deg'].to_numpy(dtype=float)
    lons = merged['lon_deg'].to_numpy(dtype=float)
    alts = (merged['alt_km'].to_numpy(dtype=float) * 1000.0)
    f107 = merged['f107'].to_numpy(dtype=float)
    f107a = merged['f107a'].to_numpy(dtype=float)
    aps = np.vstack(merged['aps'].to_numpy())

    # pymsis expects lon in degrees east [-180,180], wrap if needed
    lons = ((lons + 180) % 360) - 180

    try:
        out = msis.run(times, lons, lats, alts, f107=f107, f107a=f107a, aps=aps)
    except Exception as e:
        return pd.DataFrame({'error':[f'msis.run failed: {e}'], 'n':[len(merged)]})

    # pymsis output: (N, 10) with species + T; total mass density is column 0? Actually pymsis returns structured array with names.
    rho_model = None
    if hasattr(out, 'dtype') and out.dtype.names is not None:
        # look for total mass density key
        for key in ['rho','Total','DENS','dens','mass_density']:
            if key in out.dtype.names:
                rho_model = out[key]
                break
        if rho_model is None:
            # common name in pymsis: 'RHO'
            if 'RHO' in out.dtype.names:
                rho_model = out['RHO']
    if rho_model is None:
        # fallback assume first column
        rho_model = np.asarray(out)[:,0]

    rho_model = np.asarray(rho_model, dtype=float)
    rho_meas = merged['rho_meas'].to_numpy(dtype=float)

    m = np.isfinite(rho_model) & np.isfinite(rho_meas) & (rho_model>0) & (rho_meas>0)
    if m.sum() == 0:
        return pd.DataFrame({'error':['No finite positive modeled/measured density pairs'], 'n':[0]})

    rmse = float(np.sqrt(np.mean((rho_model[m] - rho_meas[m])**2)))

    return pd.DataFrame({'rmse':[rmse], 'n':[int(m.sum())]})

def process(msiseRmse) -> pd.DataFrame:
    import numpy as np
    import pandas as pd

    if msiseRmse is None or msiseRmse.empty:
        return pd.DataFrame({'error':['msiseRmse produced no rows'], 'n':[0], 'final_str':[None], 'final':[np.nan]})

    if 'error' in msiseRmse.columns and msiseRmse['error'].notna().any():
        err = msiseRmse.loc[msiseRmse['error'].notna(), 'error'].astype(str).iloc[0]
        n = int(msiseRmse['n'].iloc[0]) if 'n' in msiseRmse.columns else 0
        return pd.DataFrame({'error':[err], 'n':[n], 'final_str':[None], 'final':[np.nan]})

    if 'rmse' not in msiseRmse.columns:
        return pd.DataFrame({'error':['rmse column missing from msiseRmse'], 'n':[0], 'final_str':[None], 'final':[np.nan]})

    rmse = float(msiseRmse['rmse'].iloc[0])
    n = int(msiseRmse['n'].iloc[0]) if 'n' in msiseRmse.columns else 0

    if not np.isfinite(rmse):
        return pd.DataFrame({'error':['rmse is not finite'], 'n':[n], 'final_str':[None], 'final':[rmse]})

    final_str = f"{rmse:.3e}"  # 4 sig figs
    return pd.DataFrame({'final':[rmse], 'final_str':[final_str], 'n':[n], 'error':[None]})

def process(finalAnswer) -> pd.DataFrame:
    # Return a single-cell numeric-like answer if available; otherwise surface error.
    if 'final_str' in finalAnswer.columns and finalAnswer['final_str'].notna().any():
        return pd.DataFrame({'value':[finalAnswer['final_str'].dropna().iloc[0]]})
    if 'final' in finalAnswer.columns and finalAnswer['final'].notna().any():
        v = float(finalAnswer['final'].dropna().iloc[0])
        return pd.DataFrame({'value':[f"{v:.3e}"]})
    err = None
    if 'error' in finalAnswer.columns and finalAnswer['error'].notna().any():
        err = str(finalAnswer['error'].dropna().iloc[0])
    return pd.DataFrame({'value':[None],'error':[err]})
